  ".ma-root .simple-modes .aff-inline-seg.active, .ma-root .simple-modes .aff-inline-seg.active:hover { background: var(--accent); border-color: var(--accent); color: #fff; }",
  ".ma-root[data-ma-theme='dark'] .simple-more > summary:hover { color: var(--text); }",
