  ".ma-root .simple-merged { font-size: 11px; color: var(--faint); border: 1px solid var(--border); border-radius: 999px; padding: 0 7px; white-space: nowrap; flex: none; }",
  ".ma-root .simple-where { font-size: 12px; color: var(--muted); min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }",
  ".ma-root .simple-where .dim { color: var(--faint); }",
